    [6331]={name="Howling Blade",quality=3,ilvl=38,reqLevel=33,sourceType="rare_npc",instructions="Drops from Skhowl.",zone="Alterac Mountains",npc="Skhowl",proc="Chance on hit: Reduces target's attack power by 30 for 30 sec."},
