    [7739]={name="Timberland Cape",quality=2,ilvl=18,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Tharnariun's Hope'. Pick it over the other reward choices.",zone="Darkshore",questName="Tharnariun's Hope",lore="The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."},
    [7746]={name="Explorers' League Commendation",quality=3,ilvl=40,reqLevel=28,sourceType="quest_reward",instructions="Reward from the quest 'Mythology of the Titans'. Starts with Librarian Mae Paledust in Ironforge. Objective: Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",zone="Scarlet Monastery",questName="Mythology of the Titans",lore="The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."},
    [7747]={name="Vile Protector",quality=3,ilvl=40,reqLevel=28,sourceType="quest_reward",instructions="Reward from the quest 'Compendium of the Fallen'. Pick it over the other reward choices. Starts with Sage Truthseeker in Thunder Bluff. Objective: Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",zone="Scarlet Monastery",questName="Compendium of the Fallen",lore="The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"},
